// Complete JLPT N4 & N5 Kanji and Vocabulary Dataset - Fully Offline Version
// This file contains all kanji, vocabulary, and radical data from kanjikana.com
// Data includes: JLPT N4, JLPT N5, and all radicals (pages 1-14)

export interface KanjiEntry {
  character: string;
  romaji: string;
  meaning: string;
  radical: string;
  wordType: string;
  similarKanji: string[];
  explanation: string;
  jlptLevel: string;
}

export interface VocabularyEntry {
  vocabulary: string;
  romaji: string;
  meaning: string;
  radical: string;
  wordType: string;
  explanation: string;
  jlptLevel: string;
  // Optional batch import fields
  id?: string;
  batchCode?: string;
  category?: string;
  theme?: string;
}

export interface RadicalInfo {
  name: string;
  origin: string;
  meaning: string;
  relatedConcepts: string;
  kanjiList: string[];
  vocabularyList: string[];
}

