// ============================================================================
// STATISTICS FUNCTION
// ============================================================================
export interface DataStatistics {
  totalKanji: number;
  totalVocabulary: number;
  totalRadicals: number;
  jlptLevels: string[];
  kanjiByLevel: Record<string, number>;
  vocabularyByLevel: Record<string, number>;
}

export function getDataStatistics(): DataStatistics {
  const jlptLevels = Array.from(
    new Set([
      ...kanjiData.map((k) => k.jlptLevel),
      ...vocabularyData.map((v) => v.jlptLevel),
    ]),
  ).sort();

  const kanjiByLevel: Record<string, number> = {};
  const vocabularyByLevel: Record<string, number> = {};

  for (const level of jlptLevels) {
    kanjiByLevel[level] = kanjiData.filter((k) => k.jlptLevel === level).length;
    vocabularyByLevel[level] = vocabularyData.filter(
      (v) => v.jlptLevel === level,
    ).length;
  }

  return {
    totalKanji: kanjiData.length,
    totalVocabulary: vocabularyData.length,
    totalRadicals: radicalData.length,
    jlptLevels,
    kanjiByLevel,
    vocabularyByLevel,
  };
}
